async function polls(p){const a=NOTICE.includes(me.role),[m,u]=await Promise.all([db.from("polls").select("*").order("id",{ascending:!1}),db.from("votes").select("*")]),i=u.data||[];p.innerHTML=`${a?'<div class="card"><b>New poll</b><div style="height:8px"></div><input id="pq" placeholder="Question"><div style="height:8px"></div><input id="po" placeholder="Options separated by commas, e.g. Yes, No"><div style="height:8px"></div><button id="pc">Start poll</button></div>':""}
 ${(m.data||[]).map(t=>{const o=String(t.options).split("|"),l=i.find(e=>String(e.poll_id)===String(t.id)&&e.mine),s=i.filter(e=>String(e.poll_id)===String(t.id)).length,d=t.status==="open";return`<div class="card"><b>${esc(t.question)}</b> <small style="color:var(--grey)">${d?"Open":"Closed"} · ${s} vote${s===1?"":"s"}</small>
  ${o.map(e=>{const n=i.filter(r=>String(r.poll_id)===String(t.id)&&r.choice===e).length,c=s?Math.round(n/s*100):0;return l||!d?`<div class="bar${l&&l.choice===e?" me":""}"><div style="width:${Math.max(c,12)}%">${esc(OPT(t,e))} · ${n} (${c}%)</div></div>`:`<button class="ghost" style="margin-top:6px" data-v="${t.id}" data-c="${esc(e)}">${esc(OPT(t,e))}</button>`}).join("")}
  ${l?`<small style="color:var(--green)">You voted: ${esc(OPT(t,l.choice))}</small>`:""}${a?`<div class="f" style="margin-top:8px">${d?`<button class="ghost" data-pc="${t.id}">Close poll</button>`:""}<button class="ghost" data-px="${t.id}">Delete</button></div>`:""}</div>`}).join("")||'<div class="card">No polls yet.</div>'}`,a&&($("#pc").onclick=async()=>{const{error:t}=await db.from("polls").insert({question:$("#pq").value.trim(),options:$("#po").value.split(",").map(o=>o.trim()).filter(Boolean).join("|")});t?toast(t.message):render()}),document.querySelectorAll("[data-v]").forEach(t=>t.onclick=async()=>{const{error:o}=await db.from("votes").insert({poll_id:+t.dataset.v,choice:t.dataset.c});o?toast(o.message):render()}),document.querySelectorAll("[data-pc]").forEach(t=>t.onclick=async()=>{await db.from("polls").update({status:"closed"}).eq("id",t.dataset.pc),render()}),document.querySelectorAll("[data-px]").forEach(t=>t.onclick=async()=>{await db.from("polls").delete().eq("id",t.dataset.px),render()})}
